import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
  // Arrange: the seeded member's address with its case changed, as the scenario states it.
  const email = USERS.member.replace("member", "Member").replace("northwind.test", "Northwind.TEST");

  // Act
  const login = await request.post("/api/auth/login", {
    data: { email, password: PASSWORD },
  });

  // Assert
  const body = await expectStatus<{ access_token: string; user: { email: string } }>(login, 200);
  expect(body.user.email).toBe(USERS.member);

  // The stored current user, read back with the issued token.
  const me = await request.get("/api/me", {
    headers: { Authorization: `Bearer ${body.access_token}` },
  });
  const profile = await expectStatus<{ email: string }>(me, 200);
  expect(profile.email).toBe(USERS.member);
});
